pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(address to, uint256 value) internal {
        vm.assume(to != address(0));
        vm.assume(value > c.balanceOf(address(this)));
        vm.assume(!c.frozenAccount(address(this)));
        vm.assume(!c.frozenAccount(to));
        uint256 fromBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { fromBefore = __r; } catch { return; }
        uint256 toBefore;
        try c.balanceOf(to) returns (uint256 __r) { toBefore = __r; } catch { return; }
        bool reverted;
        try c.transfer(to, value) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted && c.balanceOf(address(this)) == fromBefore && c.balanceOf(to) == toBefore && c.totalSupply() == c.totalSupply());
    }

    function testFuzz_run(address to, uint256 value) public {
        vm.assume(to.code.length == 0 && uint160(to) > 0xffff && to != address(this) && to != address(c) && to != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && to != 0x000000000000000000636F6e736F6c652e6c6f67 && to != 0x4e59b44847b379578588920cA78FbF26c0B4956C && to != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(to, value);
    }

    receive() external payable {}
}
